 const loadProducts=async(admin=false)=>{setLoadingProducts(true);try{const r=await api.get(admin?'/api/admin/products':'/api/products');setProducts(r.data.products??[]);}catch{setNotice('Products are temporarily unavailable. Please refresh.');}finally{setLoadingProducts(false);}};
