 const openProduct=async(p:Product)=>{window.history.pushState({},'', '/product/'+p.id);setSelectedProduct(p);document.title=p.name+' | K-M Promotions';setReviewNotice('');setReviewForm({name:'',rating:'5',review:''});try{const r=await api.get('/api/reviews/'+p.id);setProductReviews(r.data.reviews??[]);}catch{setProductReviews([]);}};
 const closeProduct=()=>{setSelectedProduct(null);if(window.location.pathname.startsWith('/product/'))window.history.pushState({},'', '/');document.title='K-M Promotions | Discover. Promote. Earn.';};
 const submitReview=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!selectedProduct)return;try{const r=await api.post('/api/reviews',{productId:selectedProduct.id,...reviewForm,rating:Number(reviewForm.rating)});setReviewNotice(r.data.message||'Review submitted for approval.');setReviewForm({name:'',rating:'5',review:''});}catch{setReviewNotice('Could not submit your review. Please try again.');}};
 const subscribeNewsletter=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setNewsletterMessage('');try{const r=await api.post('/api/newsletter',{email:newsletterEmail,consent:newsletterConsent});setNewsletterMessage(r.data.message||'You are subscribed.');setNewsletterEmail('');setNewsletterConsent(false);}catch{setNewsletterMessage('Subscription failed. Please check your email and try again.');}};
 const saveCampaign=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();try{await api.post('/api/admin/campaigns',campaignForm);setCampaignForm({name:'',channel:'Social media',destinationUrl:'',budget:'',startDate:'',endDate:'',status:'draft',notes:''});setNotice('Campaign saved.');await loadCampaigns();}catch{setAuthError('Could not save campaign. Check the campaign details and destination URL.');}};
 const updateCampaign=async(c:Campaign,status:string)=>{try{await api.put('/api/admin/campaigns/'+c.id,{status});setCampaigns(current=>current.map(item=>item.id===c.id?{...item,status}:item));}catch{setAuthError('Could not update campaign status.');}};
 const deleteCampaign=async(c:Campaign)=>{if(!window.confirm('Delete campaign '+c.name+'?'))return;try{await api.delete('/api/admin/campaigns/'+c.id);setCampaigns(current=>current.filter(item=>item.id!==c.id));setNotice('Campaign deleted.');}catch{setAuthError('Could not delete campaign.');}};
 useEffect(()=>{if(adminOpen)return;let hideTimer:ReturnType<typeof setTimeout>|undefined;const showNotice=()=>{if(!assistantOpen){setAssistantNotice(true);hideTimer=window.setTimeout(()=>setAssistantNotice(false),6500);}};const first=window.setTimeout(showNotice,10000);const repeat=window.setInterval(showNotice,10000);return()=>{window.clearTimeout(first);window.clearInterval(repeat);if(hideTimer)window.clearTimeout(hideTimer);};},[adminOpen,assistantOpen]);
 const sendAssistantMessage=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const message=assistantInput.trim();if(!message||assistantBusy)return;const next=[...assistantMessages,{role:'user' as const,content:message}];setAssistantMessages(next);setAssistantInput('');setAssistantBusy(true);setAssistantNotice(false);try{const r=await api.post('/api/assistant',{message,history:next.slice(-9,-1)});setAssistantMessages(current=>[...current,{role:'assistant',content:r.data.answer||'I could not prepare an answer just now. Please try again.'}]);}catch{setAssistantMessages(current=>[...current,{role:'assistant',content:'I’m temporarily unable to connect. Please try again in a moment, or use the WhatsApp button to contact K-M Promotions.'}]);}finally{setAssistantBusy(false);}};
 useEffect(()=>{document.title='K-M Promotions | Discover. Promote. Earn.';const desc='Discover useful products, trusted recommendations, deals and business promotion opportunities with K-M Promotions.';let meta=document.querySelector('meta[name=description]') as HTMLMetaElement|null;if(!meta){meta=document.createElement('meta');meta.name='description';document.head.appendChild(meta);}meta.content=desc;let og=document.querySelector('meta[property="og:description"]') as HTMLMetaElement|null;if(!og){og=document.createElement('meta');og.setAttribute('property','og:description');document.head.appendChild(og);}og.content=desc;},[]);
 useEffect(()=>{let live=true;auth.getUser().then(u=>{if(live)setUser(u);}).catch(()=>{}).finally(()=>{if(live)setAuthReady(true);});loadProducts();return()=>{live=false;};},[]);
