 useEffect(()=>{const syncProductRoute=()=>{const match=window.location.pathname.match(/^\/product\/([^/]+)$/);if(!match){setSelectedProduct(null);return;}const found=products.find(p=>p.id===decodeURIComponent(match[1]));if(found){setSelectedProduct(found);document.title=found.name+' | K-M Promotions';api.get('/api/reviews/'+found.id).then(r=>setProductReviews(r.data.reviews??[])).catch(()=>setProductReviews([]));}};window.addEventListener('popstate',syncProductRoute);if(products.length)syncProductRoute();return()=>window.removeEventListener('popstate',syncProductRoute);},[products]);
 const signIn=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setAuthError('');try{await auth.signIn(loginEmail,loginPassword);window.location.reload();}catch{setAuthError('Sign-in failed. Check your administrator email and password.');}};
