 const updateEnquiryStatus=async(q:Enquiry,status:string)=>{try{await api.put('/api/admin/enquiries/'+q.id,{status});setEnquiries(current=>current.map(item=>item.id===q.id?{...item,status}:item));setNotice('Enquiry status updated.');}catch{setAuthError('Could not update enquiry status.');}};
 const exportEnquiries=()=>{const rows=[['Name','Email','Business','Type','Message','Status','Created'],...enquiries.map(q=>[q.name,q.email,q.business??'',q.type,q.message,q.status??'new',q.createdAt])];const csv=rows.map(row=>row.map(value=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join(String.fromCharCode(13,10));const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='km-promotion-enquiries.csv';link.click();URL.revokeObjectURL(url);};
